/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var Axis = require( '@stdlib/plot/vega/axis/ctor' );
var Title = require( '@stdlib/plot/vega/title/ctor' );
var LinearScale = require( '@stdlib/plot/vega/scale/linear' );
var Autosize = require( '@stdlib/plot/vega/autosize/ctor' );
var Padding = require( '@stdlib/plot/vega/padding/ctor' );
var paired2tidy = require( '@stdlib/plot/vega/data/tidy/from-paired-arrays' );


// MAIN //

/**
* Serializes a plot to JSON.
*
* @private
* @returns {Object} JSON object
*/
function toJSON() {
	var autosize;
	var padding;
	var xScale;
	var yScale;
	var xAxis;
	var yAxis;
	var title;
	var data;
	var spec;
	var i;

	title = new Title({
		'text': this.title
	});

	autosize = new Autosize({
		'type': 'none',
		'contains': 'padding'
	});

	padding = new Padding({
		'bottom': this.paddingBottom,
		'left': this.paddingLeft,
		'right': this.paddingRight,
		'top': this.paddingTop
	});

	xScale = new LinearScale({
		'name': 'xScale',
		'domain': this.xDomain,
		'range': this.xRange
	});

	yScale = new LinearScale({
		'name': 'yScale',
		'domain': this.yDomain,
		'range': this.yRange
	});

	xAxis = new Axis({
		'scale': xScale.name,
		'orient': this.xAxisOrient,
		'title': this.xLabel
	});
	if ( this.xNumTicks ) {
		xAxis.tickCount = this.xNumTicks;
	}

	yAxis = new Axis({
		'scale': yScale.name,
		'orient': this.yAxisOrient,
		'title': this.yLabel,
		'domain': false
	});
	if ( this.yNumTicks ) {
		yAxis.tickCount = this.yNumTicks;
	}
	data = paired2tidy( this.x, this.y, [ 'table1', 'table2' ], [ 'x', 'y' ] );
	for ( i = 0; i < data.length; i++ ) {
		data[ i ] = data[ i ].toJSON();
	}

	spec = {
		'$schema': 'https://vega.github.io/schema/vega/v6.json',
		'description': this.description,
		'title': title.toJSON(),
		'width': this.width,
		'height': this.height,
		'autosize': autosize.toJSON(),
		'padding': padding.toJSON(),
		'scales': [
			xScale.toJSON(),
			yScale.toJSON()
		],
		'axes': [
			xAxis.toJSON(),
			yAxis.toJSON()
		],
		'marks': [
			{
				'type': 'line',
				'from': {
					'data': 'table1'
				},
				'encode': {
					'enter': {
						'stroke': {
							'value': this.colors[ 0 ]
						},
						'x': {
							'scale': 'xScale',
							'field': 'x'
						},
						'y': {
							'scale': 'yScale',
							'field': 'y'
						},
						'defined': {
							'signal': 'isValid(datum.y)'
						}
					},
					'update': {
						'strokeDash': {
							'value': [ 5, 1, 1, 1 ]
						}
					}
				}
			},
			{
				'type': 'line',
				'from': {
					'data': 'table2'
				},
				'encode': {
					'enter': {
						'stroke': {
							'value': this.colors[ 1 ]
						},
						'x': {
							'scale': 'xScale',
							'field': 'x'
						},
						'y': {
							'scale': 'yScale',
							'field': 'y'
						},
						'defined': {
							'signal': 'isValid(datum.y)'
						}
					},
					'update': {
						'strokeDash': {
							'value': []
						}
					}
				}
			}
		],
		'data': data
	};
	return spec;
}


// EXPORTS //

module.exports = toJSON;
